/* TEAM CODE (owner: Jack - audio input and SD storage) - written by the BJT2 team, not generated by STM32CubeMX. */
/* Authors: Jack; Brendon (integrator) added file_index_list_newest() (29 Oct 2026) and the streaming
 * scan fi_scan_* (29-30 Oct 2026, best-ui), with an AI coding assistant. file_index.h says what
 * each function does; the scan is pure logic over the storage_port.h root iterator. */
/* The File list: the WAV files in the card root that go on it (the
 * "playable" rule in file_index.h), and a window of up to 16 of their names.
 *
 * The firmware uses only the streaming scan (fi_scan_*, at the bottom). No
 * task of its own: jack_audio_sd.c runs it inside JackStorageTask:
 *   - storage_rescan(): a count-only scan after a mount, a recording, a
 *     delete or the user's retry (the total for the status, the last name);
 *   - storage_play_name(): a whole scan, for a PLAY that gives a list
 *     position instead of a name;
 *   - a StorageReq_t for names (TonyTask, BrendonTask): fi_scan_begin(), then
 *     one fi_scan_step() per loop pass (16 root entries per pass while
 *     recording or playing, no limit otherwise) until the window is ready.
 * One scan: pass 1 counts the playable files and finds the anchor name,
 * pass 2 copies the names of the window. A changed list generation (gen)
 * restarts it, so it never counts one list and copies from another.
 * The old batch listing (file_index_list, file_index_list_newest) and
 * file_index_select() are used only by their tests now. */
#include "file_index.h"
#include "wav_storage.h"
#include <string.h>
#include <ctype.h>

/* Directory listing buffer size used internally when talking to
 * Storage_ListDir(). This is independent of the caller's max_entries -
 * we may need to look through more raw entries than we keep, in order
 * to filter out non-.WAV files. */
#define FILE_INDEX_RAW_SCAN_CAPACITY 64U

static int has_wav_extension(const char *name)
{
    const size_t len = strlen(name);
    if (len < 4U)
    {
        return 0;
    }
    const char *ext = &name[len - 4U];
    return (ext[0] == '.') &&
           (tolower((unsigned char)ext[1]) == 'w') &&
           (tolower((unsigned char)ext[2]) == 'a') &&
           (tolower((unsigned char)ext[3]) == 'v');
}

storage_result_t file_index_list(file_entry_t *out, size_t max_entries, size_t *out_count)
{
    if ((out == NULL) || (out_count == NULL) || (max_entries == 0U))
    {
        return STORAGE_INVALID_ARG;
    }

    *out_count = 0U;

    storage_dir_entry_t raw[FILE_INDEX_RAW_SCAN_CAPACITY];
    size_t raw_count = 0U;

    const storage_result_t list_result =
        Storage_ListDir(raw, FILE_INDEX_RAW_SCAN_CAPACITY, &raw_count);

    if (list_result == STORAGE_CORRUPT)
    {
        return STORAGE_CORRUPT;
    }
    /* STORAGE_TRUNCATED from the raw scan just means there were more than
     * FILE_INDEX_RAW_SCAN_CAPACITY raw directory entries; we still filter
     * and return what we did see, and report our own truncation status
     * below based on max_entries. */

    size_t kept = 0U;
    int truncated = 0;

    for (size_t i = 0U; i < raw_count; i++)
    {
        if (!has_wav_extension(raw[i].name))
        {
            continue;
        }
        if (kept >= max_entries)
        {
            truncated = 1;
            break;
        }
        (void)strncpy(out[kept].name, raw[i].name, sizeof(out[kept].name) - 1U);
        out[kept].name[sizeof(out[kept].name) - 1U] = '\0';
        out[kept].size_bytes = raw[i].size_bytes;
        kept++;
    }

    *out_count = kept;

    if ((list_result == STORAGE_TRUNCATED) || (truncated != 0))
    {
        return STORAGE_TRUNCATED;
    }

    return STORAGE_OK;
}

/* TEAM CODE (written by Brendon, integrator, 29 Oct 2026, best-ui): is_playable_wav() and file_index_list_newest() below */
/* A .WAV worth listing: more than a bare header (a 0-byte or header-only
 * file has no samples and is refused at play start), and not a Mac
 * "._NAME.WAV" metadata file, which reads back as "_NAME~1.WAV". */
static int is_playable_wav(const storage_dir_entry_t *entry)
{
    return has_wav_extension(entry->name) &&
           (entry->name[0] != '_') &&
           (entry->size_bytes > WAV_HEADER_SIZE);
}

storage_result_t file_index_list_newest(file_entry_t *out, size_t max_entries, size_t *out_count)
{
    if ((out == NULL) || (out_count == NULL) || (max_entries == 0U))
    {
        return STORAGE_INVALID_ARG;
    }

    *out_count = 0U;

    storage_dir_entry_t raw[FILE_INDEX_RAW_SCAN_CAPACITY];
    size_t raw_count = 0U;

    const storage_result_t list_result =
        Storage_ListDir(raw, FILE_INDEX_RAW_SCAN_CAPACITY, &raw_count);

    if (list_result == STORAGE_CORRUPT)
    {
        return STORAGE_CORRUPT;
    }
    /* STORAGE_TRUNCATED from the raw scan is handled as in file_index_list(). */

    /* Count the qualifying files first, so the oldest extras can be passed
     * over and the newest max_entries kept in report order. */
    size_t playable = 0U;
    for (size_t i = 0U; i < raw_count; i++)
    {
        if (is_playable_wav(&raw[i]))
        {
            playable++;
        }
    }

    size_t to_skip = (playable > max_entries) ? (playable - max_entries) : 0U;
    size_t kept = 0U;

    for (size_t i = 0U; i < raw_count; i++)
    {
        if (!is_playable_wav(&raw[i]))
        {
            continue;
        }
        if (to_skip > 0U)
        {
            to_skip--;
            continue;
        }
        (void)strncpy(out[kept].name, raw[i].name, sizeof(out[kept].name) - 1U);
        out[kept].name[sizeof(out[kept].name) - 1U] = '\0';
        out[kept].size_bytes = raw[i].size_bytes;
        kept++;
    }

    *out_count = kept;

    if ((list_result == STORAGE_TRUNCATED) || (playable > max_entries))
    {
        return STORAGE_TRUNCATED;
    }

    return STORAGE_OK;
}

storage_result_t file_index_select(const file_entry_t *list,
                                    size_t count,
                                    size_t index,
                                    file_entry_t *out_selected)
{
    if ((list == NULL) || (out_selected == NULL))
    {
        return STORAGE_INVALID_ARG;
    }
    if (index >= count)
    {
        return STORAGE_NOT_FOUND;
    }
    *out_selected = list[index];
    return STORAGE_OK;
}

/* TEAM CODE (written by Brendon, integrator, 29-30 Oct 2026, best-ui): the streaming scan fi_scan_* below */
/* ------------------------------------------------------------------------ */
/* Streaming scan (see file_index.h for the two passes)                      */
/* ------------------------------------------------------------------------ */

/* Back to the first entry of pass 1, with nothing found yet. */
static void fi_rewind(fi_scan_t *s)
{
    if (s->open)
    {
        Storage_DirClose();
        s->open = false;
    }
    s->pass = FI_PASS_COUNT;
    s->seen = 0U;
    s->total = 0U;
    s->found = FI_INDEX_NONE;
    s->first = 0U;
    s->count = 0U;
    s->last[0] = '\0';
}

/* The scan is over: close the root and keep the result. */
static void fi_finish(fi_scan_t *s, storage_result_t result)
{
    if (s->open)
    {
        Storage_DirClose();
        s->open = false;
    }
    s->result = result;
    if (result != STORAGE_OK)
    {
        s->count = 0U;
    }
    s->pass = FI_PASS_DONE;
}

/* Where the window starts: up to FI_WINDOW_HALF names before its centre,
 * and never so late that it would hold fewer than FI_WINDOW names. */
static uint16_t fi_window_first(const fi_scan_t *s)
{
    uint16_t centre;
    if (s->found != FI_INDEX_NONE)
    {
        centre = s->found;
    }
    else if ((s->want == FI_INDEX_LAST) || (s->want >= s->total))
    {
        centre = (uint16_t)(s->total - 1U);
    }
    else
    {
        centre = s->want;
    }

    uint16_t first = (centre > FI_WINDOW_HALF) ? (uint16_t)(centre - FI_WINDOW_HALF) : 0U;
    const uint16_t latest_first = (s->total > FI_WINDOW) ? (uint16_t)(s->total - FI_WINDOW) : 0U;
    if (first > latest_first)
    {
        first = latest_first;
    }
    return first;
}

/* How many names the window holds: FI_WINDOW, or fewer at the end of a short list. */
static uint8_t fi_window_len(const fi_scan_t *s)
{
    const uint16_t after_first = (uint16_t)(s->total - s->first);
    return (uint8_t)((after_first < FI_WINDOW) ? after_first : FI_WINDOW);
}

/* Pass 1, one playable file: count it, note it as the last name, and see
 * whether it is the anchor. */
static void fi_count_entry(fi_scan_t *s, const char *name)
{
    if (s->seen >= FI_MAX_FILES)
    {
        return;                       /* the count stops at FI_MAX_FILES */
    }
    const bool is_anchor = (s->anchor[0] != '\0') &&
                           (s->found == FI_INDEX_NONE) &&
                           (strncmp(name, s->anchor, FI_NAME_LEN) == 0);
    if (is_anchor)
    {
        s->found = s->seen;
    }
    (void)strncpy(s->last, name, FI_NAME_LEN - 1U);
    s->last[FI_NAME_LEN - 1U] = '\0';
    s->seen++;
    s->total = s->seen;
}

/* Pass 2, one playable file: copy it when it lies in the window. Returns
 * true once the whole window is copied (the rest need not be read). */
static bool fi_copy_entry(fi_scan_t *s, const char *name)
{
    const uint16_t position = s->seen;
    s->seen++;
    if (position < s->first)
    {
        return false;
    }
    char *slot = s->names[s->count];
    (void)strncpy(slot, name, FI_NAME_LEN - 1U);
    slot[FI_NAME_LEN - 1U] = '\0';
    s->count++;
    return (s->count >= fi_window_len(s));
}

/* The end of the root was reached. Pass 1 then sets up pass 2 (or ends a
 * count-only scan, or an empty list); pass 2 ends the scan. Returns true
 * when the scan is done. */
static bool fi_end_pass(fi_scan_t *s)
{
    Storage_DirClose();
    s->open = false;
    if ((s->pass == FI_PASS_COPY) || s->count_only || (s->total == 0U))
    {
        fi_finish(s, STORAGE_OK);
        return true;
    }
    s->first = fi_window_first(s);
    s->pass = FI_PASS_COPY;
    s->seen = 0U;
    return false;
}

void fi_scan_begin(fi_scan_t *s, uint16_t want, const char *anchor, bool count_only, uint16_t gen)
{
    if (s == NULL)
    {
        return;
    }
    (void)memset(s, 0, sizeof(*s));
    s->want = want;
    if (anchor != NULL)
    {
        (void)strncpy(s->anchor, anchor, FI_NAME_LEN - 1U);
    }
    s->count_only = count_only;
    s->gen = gen;
    s->result = STORAGE_OK;
    fi_rewind(s);
}

bool fi_scan_step(fi_scan_t *s, uint32_t max_entries, uint16_t gen)
{
    if (s == NULL)
    {
        return true;
    }
    if (s->pass == FI_PASS_DONE)
    {
        return true;
    }
    if (gen != s->gen)
    {
        /* The list changed under the scan: count it again from the start. */
        fi_rewind(s);
        s->gen = gen;
    }

    uint32_t budget = max_entries;
    while (budget > 0U)
    {
        if (!s->open)
        {
            if (Storage_DirOpen() != STORAGE_OK)
            {
                fi_finish(s, STORAGE_CORRUPT);
                return true;
            }
            s->open = true;
        }

        storage_dir_entry_t entry;
        const storage_result_t r = Storage_DirNext(&entry);
        budget--;
        s->entries_read++;

        if (r == STORAGE_NOT_FOUND)
        {
            if (fi_end_pass(s))
            {
                return true;
            }
            continue;                 /* pass 2 starts on the next entry read */
        }
        if (r != STORAGE_OK)
        {
            fi_finish(s, STORAGE_CORRUPT);
            return true;
        }
        if (!is_playable_wav(&entry))
        {
            continue;
        }
        if (s->pass == FI_PASS_COUNT)
        {
            fi_count_entry(s, entry.name);
            continue;
        }
        if (fi_copy_entry(s, entry.name))
        {
            fi_finish(s, STORAGE_OK);
            return true;
        }
    }
    return false;
}

void fi_scan_abort(fi_scan_t *s)
{
    if ((s == NULL) || (s->pass == FI_PASS_DONE))
    {
        return;
    }
    fi_rewind(s);
}

bool fi_scan_done(const fi_scan_t *s)
{
    return (s == NULL) || (s->pass == FI_PASS_DONE);
}
